H.background();
// Force on a current-carrying wire in a field:  F = B I L sin(theta).
// theta is the angle between the wire (current direction) and B.
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -6, yMax: 6 });
v.grid(); v.axes({ ticks: false });
const I = Math.max(0, P.I);              // current (A)
const B = Math.max(0, P.B);              // field strength (T)
const L = Math.max(0.2, P.L);            // wire length (m)
const thetaDeg = P.theta;                // angle between wire and B (deg)
const theta = thetaDeg * Math.PI / 180;
// uniform B field to the RIGHT (+x): draw horizontal arrows
for (let gy = -5; gy <= 5; gy += 1.6) {
  v.arrow(-7, gy, -5.4, gy, { color: H.colors.violet, width: 1.4, head: 6 });
  v.arrow(5.4, gy, 7, gy, { color: H.colors.violet, width: 1.4, head: 6 });
}
// the wire: lies at angle theta from B (the +x axis), centered at origin
const half = L / 2;
const wx = half * Math.cos(theta), wy = half * Math.sin(theta);
v.line(-wx, -wy, wx, wy, { color: H.colors.accent, width: 5 });
// current direction arrow along the wire
v.arrow(0, 0, 0.9 * wx, 0.9 * wy, { color: H.colors.good, width: 3, head: 10 });
v.text("I", wx * 0.5 + 0.3, wy * 0.5 + 0.3, { color: H.colors.good, size: 14, weight: 700 });
// Force F = B I L sin(theta), perpendicular to BOTH wire and B -> out of/into page.
// Magnitude scaled for drawing; sign of sin(theta) sets out vs in.
const F = B * I * L * Math.sin(theta);
const Fabs = Math.abs(F);
// represent the out-of-page force as a pulsing marker at the wire midpoint,
// with an arrow length proportional to F lifting the wire visually upward
