H.text("Force on a wire:  F = B·I·L·sin θ", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("B=" + B.toFixed(2) + " T  I=" + I.toFixed(1) + " A  L=" + L.toFixed(1) + " m  θ=" + thetaDeg.toFixed(0) + "°   →   F = " + F.toFixed(2) + " N", 24, 52, { color: H.colors.sub, size: 13 });
